package com.receiptledger.v1;

import android.app.Activity;import android.os.Bundle;import android.view.Gravity;import android.widget.*;import com.receiptledger.v1.persistence.SqliteReceiptStore;import com.receiptledger.v1.price.*;import com.receiptledger.v1.product.*;import java.util.*;import java.util.concurrent.*;

public final class PriceHistoryActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private SqliteReceiptStore receipts;private SqliteProductCatalogStore catalog;private PriceHistoryService service;private LinearLayout products;private TextView detail,status;private long generation;
 @Override protected void onCreate(Bundle b){super.onCreate(b);receipts=new SqliteReceiptStore(getApplicationContext());catalog=new SqliteProductCatalogStore(getApplicationContext());service=new PriceHistoryService(receipts,catalog);int p=dp(12);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(p,p,p,p);TextView title=new TextView(this);title.setText(R.string.price_history_title);title.setTextSize(23);status=new TextView(this);ScrollView productScroll=new ScrollView(this);products=new LinearLayout(this);products.setOrientation(LinearLayout.VERTICAL);productScroll.addView(products);detail=new TextView(this);detail.setTextIsSelectable(true);ScrollView detailScroll=new ScrollView(this);detailScroll.addView(detail);Button close=new Button(this);close.setText(R.string.close_library);close.setOnClickListener(v->finish());root.addView(title);root.addView(close);root.addView(status);root.addView(productScroll,new LinearLayout.LayoutParams(-1,0,0.38f));root.addView(detailScroll,new LinearLayout.LayoutParams(-1,0,0.62f));setContentView(root);loadProducts();}
 private void loadProducts(){long t=++generation;worker.execute(()->{List<CatalogProduct> list=catalog.listProducts();runOnUiThread(()->{if(t!=generation)return;products.removeAllViews();status.setText(getString(R.string.price_product_count,list.size()));for(CatalogProduct p:list){Button b=new Button(this);b.setAllCaps(false);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setText(getString(R.string.price_product_button,p.type,p.canonicalName));b.setOnClickListener(v->loadHistory(p.id));products.addView(b);}});});}
 private void loadHistory(String productId){long t=++generation;status.setText(R.string.price_loading);worker.execute(()->{try{PriceHistory h=service.history(productId);runOnUiThread(()->{if(t==generation){detail.setText(PriceHistoryFormatter.format(h));status.setText(getString(R.string.price_observation_count,h.observations.size()));}});}catch(Exception e){runOnUiThread(()->{if(t==generation)status.setText(e.getMessage());});}});}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();catalog.close();receipts.close();super.onDestroy();}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
}
